def col_to_idx(c):
    if len(c) == 1:
        return ord(c) - ord('A')
    else:
        return (ord(c[0]) - ord('A') + 1) * 26 + (ord(c[1]) - ord('A'))

def tile_to_sw(tile):
    col_str = ''.join(ch for ch in tile if ch.isalpha())
    row_num = int(''.join(ch for ch in tile if ch.isdigit()))
    return col_to_idx(col_str) * 600, (row_num - 1) * 600

